fn r(p:&str)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn med(mut x:Vec<f64>)->f64{x.sort_by(f64::total_cmp);x[x.len()/2]}
fn seal(){fn walk(p:&Path,b:&Path,m:&mut BTreeMap<String,String>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,b,m)}else{let rel=p.strip_prefix(b).unwrap().display().to_string();if rel!="SHA256SUMS"&&rel!="artifact-index.json"{m.insert(rel,hash(&p));}}}}let base=Path::new(D);let mut m=BTreeMap::new();walk(base,base,&mut m);save(base.join("artifact-index.json"),&json!(m));m.insert("artifact-index.json".into(),hash(base.join("artifact-index.json")));fs::write(base.join("SHA256SUMS"),m.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();for(p,h)in &m{assert_eq!(hash(base.join(p)),*h);}println!("Sealed {} hashes / {} files",m.len(),m.len()+1);}
fn archive(){let a=read(r("analysis.json"));let pins=read(r("pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let mut relocations=vec![];for(p,h)in read(r("initial-analysis/pins.json")).as_object().unwrap(){if hash(p)!=h.as_str().unwrap(){let q=r("initial-analysis").join(Path::new(p).file_name().unwrap());assert_eq!(hash(&q),h.as_str().unwrap());relocations.push(json!({"initial_path":p,"preserved_path":q,"sha256":h}));}}
let decoded=read(r("decoded-events.json"));let(mut records,mut bytes)=(0usize,0usize);let mut last_kinds=BTreeMap::new();for g in decoded.as_array().unwrap(){let es:Vec<[u64;10]>=serde_json::from_value(g["events_in_original_order"].clone()).unwrap();let restored:Vec<u8>=es.iter().flat_map(|e|e.iter().flat_map(|v|v.to_le_bytes())).collect();assert_eq!(format!("{:x}",Sha256::digest(&restored)),g["sha256"]);assert_eq!(restored,fs::read(g["file"].as_str().unwrap()).unwrap());records+=es.len();bytes+=restored.len();let e=es.iter().filter(|e|e[8]!=0).max_by_key(|e|e[6]).unwrap();*last_kinds.entry(e[2]).or_insert(0usize)+=1;}assert_eq!(records,11943);assert_eq!(bytes,955440);assert_eq!(last_kinds.get(&25),Some(&9));
let mut windows=BTreeMap::new();let mut cpu=BTreeMap::new();for q in["a","kh","g2"]{let mut largest_gaps=vec![];let mut fractions=vec![];let mut count=0;let mut cpus=vec![];for graph in a["per_graph"].as_array().unwrap(){let qs=&graph["queries"][q];let gaps=qs["window_service_gaps"].as_array().unwrap();count+=gaps.len();let max=gaps.iter().max_by_key(|v|v["gap_ns"].as_u64().unwrap()).unwrap();largest_gaps.push(max["gap_ns"].as_u64().unwrap()as f64/1e6);fractions.push(max["other_window_span_fraction"].as_f64().unwrap());let sum:u64=qs["last_serial_to_return"]["by_logical_query"].as_object().unwrap().iter().filter(|(name,_)|name.as_str()!=q&&name.as_str()!="unclassified").map(|(_,v)|v["fully_contained_CPU_ns"].as_u64().unwrap()).sum();cpus.push(sum as f64/1e6);}windows.insert(q,json!({"window_callbacks":count,"median_largest_window_service_return_gap_ms":med(largest_gaps),"median_other_window_span_fraction_for_largest_gap":med(fractions)}));cpu.insert(q,med(cpus));}
let history=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-23-universal-g2-bucket-bands/conclusions.json");let h=read(history);assert_eq!(h["status"],"RejectedLocalSpeedGate");let review=json!({"raw_records":records,"reconstructed_bytes":bytes,"raw_reconstructed_exact":true,"final_pins_verified":pins.as_object().unwrap().len(),"initial_pin_relocations":relocations,"last_serial_kind_counts":last_kinds,"kind25_definition":"weighted_affine serial leaf callback","window_service_gaps":windows,"median_fully_contained_foreign_CPU_ms_after_last_serial":cpu,"prior_range_experiment":{"path":history,"sha256":hash(history),"status":h["status"],"bands2_over_OFF":h["results"]["bands2"]["controls"]["off"]["median_ratio"],"bands4_over_OFF":h["results"]["bands4"]["controls"]["off"]["median_ratio"]},"new_tests":4,"new_SDK_requests":0,"new_proofs":0,"independent_proof_ledger":17811,"production_changed":false,"adopted":false,"next":"Audit/instrument G2 scalar preparation/decomposition fold service with unchanged task geometry; retain prior failed ordering/partition policies"});save(r("review.json"),&review);
let mut md=String::from("# Query return versus covered serial service\n\n**G2 contains the last covered serial-service event in all nine saved main graphs.** K/H returns last in five graphs and G2 in four; window callback returns have the same split. The query-return labels therefore do not identify which query performed the last covered arithmetic service. This is an offline diagnostic, with no optimization or new proof timing.\n\n## Attribution\n\nThe analysis reuses the fixed nine accepted175 service-trace graphs, covering rounds 0/15/30 in three processes. Logical parent IDs assign each event to its query/window; physical worker IDs identify where it ran. For each query, the table examines the interval from its last covered serial event to query return, on the worker owning that query root. A foreign service span belongs to another logical query on that same physical worker.\n\n|Query|Median interval ms|Median foreign service-span overlap ms|Median per-graph foreign span fraction|Median fully contained foreign CPU ms|\n|---|---:|---:|---:|---:|\n");
for q in["a","kh","g2"]{let v=&a["queries"][q]["last_serial_to_return"];writeln!(md,"|{q}|{:.6}|{:.6}|{:.2}%|{:.6}|",v["median_interval_ms"].as_f64().unwrap(),v["median_foreign_service_span_overlap_ms"].as_f64().unwrap(),v["median_foreign_span_fraction"].as_f64().unwrap()*100.,cpu[q]).unwrap();}
md+="\nMedians are calculated independently and need not add or divide exactly. Elapsed service spans include any descheduling inside the recorded leaf. Exact thread-CPU deltas are summed only for leaves entirely inside an interval; partially clipped leaves retain unknown CPU rather than a prorated estimate. Uncovered elapsed spans are neither idle time nor removable work.\n\nK/H's median last-window-callback-to-query-return interval is only 0.059402 ms, while its last-covered-service-to-query-return interval is 2.530101 ms. Much of the separation therefore lies within callback lifetimes. The per-window analysis includes service from sibling windows of the same query as well as other queries.\n\n|Query|Window callbacks, all graphs|Median largest per-graph service→callback-return gap ms|Median other-window span fraction in that largest gap|\n|---|---:|---:|---:|\n";
for q in["a","kh","g2"]{let w=&windows[q];writeln!(md,"|{q}|{}|{:.6}|{:.2}%|",w["window_callbacks"],w["median_largest_window_service_return_gap_ms"].as_f64().unwrap(),w["median_other_window_span_fraction_for_largest_gap"].as_f64().unwrap()*100.).unwrap();}
md+="\nThe last covered event is a G2 `weighted_affine` serial leaf in all nine graphs: six 256-bucket leaves and three 64-bucket leaves. This identifies the final covered event, not the exclusive bottleneck, all work on the critical path, or a recoverable proof-time fraction. Preparation, normalization, Horner assembly, coordinator work and other unrecorded service remain outside the covered set. A late query or callback can include service logically owned elsewhere.\n\n## G2 preparation remains unresolved\n\nThe median G2 query-entry-to-input-marker interval is 2.051028 ms. Foreign service spans on its owner cover a median 0.297852 ms, with a median per-graph fraction of 14.52%. That leaves most of this interval unattributed by the existing leaf hooks. It cannot be called two milliseconds of scalar-conversion CPU or two milliseconds of removable waiting. The next useful measurement is preparation/decomposition service at the actual Rayon fold boundaries, while preserving task geometry and qualifying observer overhead.\n\nStarting B first was already rejected in the older query-order study; completing G1 queries before G2 also regressed in the whole-query-wave study. This analysis supplies no reason to repeat those policies unchanged. The initial bucket-range audit likewise found that the 23 October experiment already borrowed full inputs into disjoint magnitude bands without point copies or an index plan: two/four bands regressed 4.59%/6.43% against fresh OFF. That ownership mechanism is closed.\n\n## Fidelity and scope\n\nAll 11,943 original 80-byte records reconstruct exactly, totaling 955,440 bytes. Raw hashes match the published service-trace summaries. Original GRAPH thread lengths, zero-drop counts, per-worker slot IDs, logical parent containment, acyclic ancestry and non-overlapping nonforking serial leaves pass. Recomputed query/window boundaries and covered serial CPU totals match the earlier summaries. All 200 final source/data/helper pins close, including all 175 production sources.\n\nThree initial decoder/interval tests pass. After inspecting the initial result, an explicitly named exploratory expansion adds the last-own-service and per-window analyses, plus one new sibling-window ownership test. The three initial tests are inherited; the new test runs separately. Original analysis, source, binaries' identities, logs and pins remain preserved, with checked relocations for files replaced by the expanded analyzer. No capture, proof or native prover suite is rerun. [Design and expansion](artifacts/design.md), [all per-graph intervals](artifacts/analysis.json), [decoded raw records](artifacts/decoded-events.json), [review](artifacts/review.json).\n\nThe earlier service-trace overhead qualification remains as originally reported. It does not make these observations unbiased or turn span coverage into a causal scheduler model. No ideal schedule, immutable latency bound, AWS/Aeglos, phone/ARM/TEE, giant-circuit or memory-pressure result follows. Zero new SDK requests, exports or verifier calls occur; the independent proof ledger stays 17,811. Production and accepted timings remain unchanged.\n\n## Inherited CPU and Metal comparison\n\nThese are accepted local measurements against supplied historical M5 references. Primary peak RSS remains 134 MiB. The accepted full-performance-gate failure and physical16 calibration engineering exception remain.\n\n|Shape|Accepted ms|M5 CPU ms|CPU speedup|M5 Metal ms|Metal speedup|CPU 10× target ms|\n|---|---:|---:|---:|---:|---:|---:|\n";
for q in["1x2","2x2","4x2","8x2","12x2","16x2","24x2","merge-24x1"]{let v=&a["inherited_M5"][q];writeln!(md,"|{q}|{:.6}|{:.0}|{:.3}×|{:.0}|{:.3}×|{:.1}|",v["accepted_ms"].as_f64().unwrap(),v["cpu_reference_ms"].as_f64().unwrap(),v["cpu_speedup"].as_f64().unwrap(),v["metal_reference_ms"].as_f64().unwrap(),v["metal_speedup"].as_f64().unwrap(),v["required_ms_for_CPU10x"].as_f64().unwrap()).unwrap();}md+="\nAccepted 54→1 remains 162.250464 ms without a supplied M5 reference. The all-eight CPU 10× goal remains active and unmet (0/8).\n";
let base=Path::new(D);let d=base.join("artifacts");fs::create_dir_all(&d).unwrap();fs::write(base.join("README.md"),md).unwrap();for f in["design.md","analyze.rs","expanded.rs","expand.rs","archive.rs","analysis.json","analysis.log","decoded-events.json","pins.json","review.json","tests.log","expanded-tests.log","initial-analysis/analyze.rs","initial-analysis/design.md","initial-analysis/pins.json","initial-analysis/analysis.json","initial-analysis/analysis.log","initial-analysis/tests.log"]{let to=d.join(f);fs::create_dir_all(to.parent().unwrap()).unwrap();fs::copy(r(f),&to).unwrap();assert_eq!(hash(r(f)),hash(to));}save(d.join("initial-binary-hashes.json"),&json!({"analyze":hash(r("initial-analysis/analyze")),"tests":hash(r("initial-analysis/analyze-tests"))}));seal();println!("Offline11943events/955440bytes,200pinsclosed; lastcoveredG2 9/9; noSDK/proofs");}
